/**
 * User-facing configuration for WebAPKify.
 *
 * This file is meant to be authored manually by app developers in
 * `webapkify.config.ts`.
 *
 * Only `appName` and `appId` are required.
 * Everything else is optional and receives a default in `applyDefaults()`.
 *
 * A typical config looks like:
 *
 * @example ```ts
 * import type { WebAPKifyConfig } from 'webapkify'
 *
 * export default {
 *   appName: 'My App',
 *   appId: 'com.example.myapp',
 * } satisfies WebAPKifyConfig
 * ```
 */
export interface WebAPKifyConfig {
    /**
     * Human-readable application name shown to users.
     *
     * This is typically used as the Android app label.
     *
     * @example 'My App'
     * @required
     */
    appName: string;
    /**
     * Unique Android application ID / package name.
     *
     * This must be globally unique if you ever publish the app.
     * It usually follows reverse-domain notation.
     *
     * @example 'com.example.myapp'
     * @required
     */
    appId: string;
    /**
     * Internal Android version number.
     *
     * Users normally never see this.
     * It should increase every time you publish an update.
     *
     * @default 1
     * @example 42
     */
    versionCode?: number;
    /**
     * Human-readable version string shown in app metadata.
     *
     * @default '1.0.0'
     * @example '2.3.4'
     */
    versionName?: string;
    /**
     * Base name for generated APK artifacts.
     *
     * If omitted, WebAPKify generates one by slugifying `appName`.
     *
     * @default slugify(appName)
     * @example 'my-app'
     */
    artifact?: string;
    /**
     * Path to the built web app directory that should be bundled into the APK.
     *
     * This should usually point at your frontend build output.
     *
     * @default './dist'
     * @example './dist'
     * @example './build'
     */
    webDir?: string;
    /**
     * Minimum Android SDK version supported by the generated app.
     *
     * Devices below this API level will not be able to install the app.
     *
     * @default 26
     */
    minSdk?: number;
    /**
     * Android compile SDK version used when compiling the native wrapper.
     *
     * This should usually track a recent Android SDK.
     *
     * @default 35
     */
    compileSdk?: number;
    /**
     * Android target SDK version declared by the generated app.
     *
     * This affects platform behavior and Play policy expectations.
     *
     * @default 35
     */
    targetSdk?: number;
    /**
     * Android Build Tools version used for the native build.
     *
     * @default '35.0.0'
     */
    buildToolsVersion?: string;
    /**
     * Path to the main launcher icon image.
     *
     * A large square PNG is recommended.
     *
     * @default undefined
     * @recommended 1024x1024
     * @example './icon.png'
     */
    icon?: string;
    /**
     * Path to the adaptive icon foreground image.
     *
     * Used for Android adaptive icons.
     * If omitted, only the standard icon setup is used.
     *
     * @default undefined
     * @example './icon-fg.png'
     */
    adaptiveIconForeground?: string;
    /**
     * Path to the monochrome icon used by newer Android launchers and themed icons.
     *
     * If omitted, no monochrome icon is generated.
     *
     * @default undefined
     * @example './icon-mono.png'
     */
    monochromeIcon?: string;
    /**
     * Background color used behind the adaptive icon foreground.
     *
     * @default '#FFFFFF'
     * @example '#000000'
     */
    adaptiveIconBackground?: string;
    /**
     * WebView behavior and runtime browser settings.
     *
     * Every field here is optional.
     * If omitted, WebAPKify applies a secure/default-friendly configuration.
     */
    webview?: {
        /**
         * Enables JavaScript execution inside the WebView.
         *
         * Most modern SPAs require this.
         *
         * @default true
         */
        javaScriptEnabled?: boolean;
        /**
         * Allows JavaScript to automatically open windows.
         *
         * Usually keep this disabled unless your app explicitly depends on it.
         *
         * @default false
         */
        javaScriptCanOpenWindowsAutomatically?: boolean;
        /**
         * Enables DOM storage APIs such as `localStorage` and `sessionStorage`
         * at the WebView level.
         *
         * Many web apps depend on this.
         *
         * @default true
         */
        domStorageEnabled?: boolean;
        /**
         * Enables the legacy WebView database storage APIs.
         *
         * This is usually unnecessary for modern apps.
         *
         * @default false
         */
        databaseEnabled?: boolean;
        /**
         * Allows the WebView to use geolocation APIs.
         *
         * This only enables the feature at the WebView level.
         * Your app may still need Android permissions and runtime permission handling.
         *
         * @default false
         */
        geolocationEnabled?: boolean;
        /**
         * Allows mixed content, meaning HTTP resources loaded inside HTTPS pages.
         *
         * This is generally less secure and should stay disabled unless you know
         * exactly why you need it. Android WebView exposes mixed-content behavior
         * through WebSettings because loading insecure subresources weakens page
         * security.
         *
         * @default false
         */
        allowMixedContent?: boolean;
        /**
         * Enables built-in zoom controls in the WebView engine.
         *
         * @default true
         */
        builtInZoomControls?: boolean;
        /**
         * Shows on-screen zoom buttons.
         *
         * This is usually disabled for a cleaner UI.
         *
         * @default false
         */
        displayZoomControls?: boolean;
        /**
         * Overrides the WebView user agent string.
         *
         * Leave undefined unless you explicitly need a custom UA for server-side
         * detection, analytics, or compatibility workarounds.
         *
         * @default undefined
         * @example 'MyApp/1.0'
         */
        userAgentString?: string;
        /**
         * Allows JavaScript running from `file://` pages to access other `file://` URLs.
         *
         * This is potentially dangerous and should usually remain disabled.
         *
         * @default false
         */
        allowFileAccessFromFileURLs?: boolean;
        /**
         * Allows JavaScript running from `file://` pages to access any origin.
         *
         * This is highly permissive and should almost always remain disabled.
         *
         * @default false
         */
        allowUniversalAccessFromFileURLs?: boolean;
        /**
         * Page text zoom percentage.
         *
         * `100` means normal size.
         *
         * @default 100
         */
        textZoom?: number;
        /**
         * Whether image loading is enabled.
         *
         * @default true
         */
        loadsImagesAutomatically?: boolean;
        /**
         * Blocks network images from loading.
         *
         * Usually keep disabled unless you intentionally want an image-free mode.
         *
         * @default false
         */
        blockNetworkImage?: boolean;
        /**
         * Blocks all network loads from the WebView.
         *
         * Useful only for highly controlled offline scenarios.
         *
         * @default false
         */
        blockNetworkLoads?: boolean;
        /**
         * WebView cache policy.
         *
         * Possible values:
         * - `'DEFAULT'`            | Cache is used when the content is there, otherwise network is used. If the content is not in the cache and the device is offline, then an error is returned.
         * - `'CACHE_ELSE_NETWORK'` | Cache is used when the content is there, otherwise network is used. If the content is not in the cache and the device is offline, then the request fails with `ERR_CACHE_MISS`.
         * - `'NO_CACHE'`           | The cache is not used, and the network is used to load the resource. If the device is offline, then the request fails with `ERR_INTERNET_DISCONNECTED`.
         * - `'CACHE_ONLY'`         | The cache is used when the content is there, otherwise the request fails with `ERR_CACHE_MISS`. The network is not used.
         *
         * @default 'DEFAULT'
         */
        cacheMode?: 'DEFAULT' | 'CACHE_ELSE_NETWORK' | 'NO_CACHE' | 'CACHE_ONLY';
        /**
         * Loads the page in overview mode when possible.
         *
         * Overview mode scales the content to fit the screen by width, which can be useful for certain types of web apps.
         *
         * @default false
         */
        loadWithOverviewMode?: boolean;
        /**
         * Enables viewport support for responsive layouts.
         *
         * Most modern web apps should keep this enabled.
         *
         * @default true
         */
        useWideViewPort?: boolean;
        /**
         * Requires a user gesture before media playback starts.
         *
         * This is safer and less surprising for users.
         *
         * @default true
         */
        mediaPlaybackRequiresUserGesture?: boolean;
        /**
         * Enables Google Safe Browsing protections in WebView where supported.
         *
         * Android documents Safe Browsing support for WebView as part of secure
         * WebView management.
         *
         * @default true
         */
        safeBrowsingEnabled?: boolean;
        /**
         * Controls WebView dark-mode behavior.
         *
         * Possible values:
         * - `'OFF'`  | Dark mode is disabled, and the WebView does not attempt to darken web content.
         * - `'ON'`   | Dark mode is enabled, and the WebView attempts to darken all web content.
         * - `'AUTO'` | Dark mode is based on the system dark theme setting. When the system is in dark theme, the WebView attempts to darken all web content. When the system is in light theme, dark mode is disabled.
         *
         * @default 'AUTO'
         *
         * Chromium documents FORCE_DARK_AUTO and related darkening behavior in
         * Android WebView internals.
         */
        forceDark?: 'OFF' | 'ON' | 'AUTO';
        /**
         * Allows WebView algorithmic darkening when supported.
         *
         * Keep this disabled unless you specifically want WebView to auto-darken
         * content more aggressively.
         *
         * @default false
         */
        algorithmicDarkeningAllowed?: boolean;
        /**
         * Enables first-party cookies in the WebView.
         *
         * Most authenticated web apps need this.
         *
         * @default true
         */
        acceptCookies?: boolean;
        /**
         * Enables third-party cookies in the WebView.
         *
         * This is more permissive and is disabled by default.
         *
         * @default false
         */
        acceptThirdPartyCookies?: boolean;
    };
    /**
     * Android permissions to declare in the generated manifest.
     *
     * Fields default to either `true` or `false` depending on what WebAPKify
     * considers safe and typical.
     */
    permissions?: {
        /**
         * Allows general internet access.
         *
         * @default true
         */
        internet?: boolean;
        /**
         * Allows reading network connectivity state.
         *
         * @default true
         */
        networkState?: boolean;
        /**
         * Allows reading Wi-Fi state.
         *
         * @default false
         */
        wifiState?: boolean;
        /**
         * Allows approximate location access.
         *
         * @default false
         */
        coarseLocation?: boolean;
        /**
         * Allows precise location access.
         *
         * @default false
         */
        fineLocation?: boolean;
        /**
         * Allows camera access.
         *
         * @default false
         */
        camera?: boolean;
        /**
         * Allows microphone recording.
         *
         * @default false
         */
        recordAudio?: boolean;
        /**
         * Allows reading legacy external storage.
         *
         * @default false
         */
        readExternalStorage?: boolean;
        /**
         * Allows writing legacy external storage.
         *
         * @default false
         */
        writeExternalStorage?: boolean;
        /**
         * Allows reading image media.
         *
         * @default false
         */
        readMediaImages?: boolean;
        /**
         * Allows reading video media.
         *
         * @default false
         */
        readMediaVideo?: boolean;
        /**
         * Allows reading audio media.
         *
         * @default false
         */
        readMediaAudio?: boolean;
        /**
         * Allows vibration.
         *
         * @default false
         */
        vibrate?: boolean;
        /**
         * Allows reacting after device boot.
         *
         * @default false
         */
        receiveBootCompleted?: boolean;
        /**
         * Allows posting notifications on Android versions that require it.
         *
         * @default false
         */
        postNotifications?: boolean;
        /**
         * Allows Bluetooth-related capabilities.
         *
         * @default false
         */
        bluetooth?: boolean;
        /**
         * Allows NFC usage.
         *
         * @default false
         */
        nfc?: boolean;
        /**
         * Allows biometric authentication APIs.
         *
         * @default false
         */
        biometric?: boolean;
        /**
         * Allows legacy fingerprint authentication APIs.
         *
         * @default false
         */
        fingerprint?: boolean;
        /**
         * Allows flashlight / camera flash usage.
         *
         * @default false
         */
        flashlight?: boolean;
        /**
         * Prevents the device from sleeping while the app requests it.
         *
         * @default false
         */
        wakeLock?: boolean;
        /**
         * Allows foreground services.
         *
         * @default false
         */
        foregroundService?: boolean;
        /**
         * Allows scheduling exact alarms.
         *
         * @default false
         */
        scheduleExactAlarm?: boolean;
    };
    /**
     * Screen orientation mode for the activity.
     *
     * @default 'unspecified'
     * @example 'portrait'
     * @example 'landscape'
     */
    orientation?: string;
    /**
     * Status bar style behavior.
     *
     * Possible values:
     * - `'default'`      | Uses the default status bar style, which may vary based on the Android version and theme.
     * - `'light'`        | Applies a light status bar style, which typically features dark icons and text for better visibility on light backgrounds.
     * - `'dark'`         | Applies a dark status bar style, which typically features light icons and text for better visibility on dark backgrounds.
     * - `'transparent'`  | Makes the status bar transparent, allowing the app content to extend behind it. This can create a more immersive experience, especially when combined with edge-to-edge display features on modern Android devices.
     *
     * @default 'default'
     */
    statusBar?: 'default' | 'light' | 'dark' | 'transparent';
    /**
     * App/theme primary color used in generated native metadata.
     *
     * @default '#FFFFFF'
     */
    themeColor?: string;
    /**
     * Background color used by the app/splash/native surfaces where applicable.
     *
     * @default '#FFFFFF'
     */
    backgroundColor?: string;
    /**
     * Whether Android backup is allowed for the app.
     *
     * @default true
     */
    allowBackup?: boolean;
    /**
     * Whether hardware acceleration is enabled.
     *
     * This is usually desirable for rendering performance.
     *
     * @default true
     */
    hardwareAccelerated?: boolean;
    /**
     * Keeps the screen on while the app is active.
     *
     * @default false
     */
    keepScreenOn?: boolean;
    /**
     * Declares right-to-left layout support.
     *
     * @default false
     */
    supportsRtl?: boolean;
    /**
     * Allows restoring app data across version changes more permissively.
     *
     * @default true
     */
    restoreAnyVersion?: boolean;
    /**
     * List of domains allowed to use cleartext HTTP traffic.
     *
     * Prefer this over globally allowing all cleartext traffic.
     * Android recommends using Network Security Configuration for fine-grained
     * cleartext rules, and `usesCleartextTraffic` becomes secondary or ignored in
     * some cases depending on API level and NSC presence.
     *
     * @default []
     * @example ['localhost', '10.0.2.2']
     */
    clearTextDomains?: string[];
    /**
     * Allows cleartext HTTP traffic for all domains.
     *
     * This is the broadest and least secure option.
     * Android warns that cleartext traffic lacks confidentiality, integrity,
     * and authenticity protections.
     *
     * @default false
     */
    allowAllClearText?: boolean;
    /**
     * Signing configuration for release builds.
     *
     * Omit this for unsigned/debug-only workflows.
     * Provide it when you need deterministic release signing.
     */
    signing?: {
        /**
         * Path to the keystore file.
         *
         * @required when `signing` is provided.
         * @example './release.jks'
         */
        storeFile: string;
        /**
         * Keystore password.
         *
         * @required when `signing` is provided.
         */
        storePassword: string;
        /**
         * Alias of the key inside the keystore.
         *
         * @required when `signing` is provided.
         */
        keyAlias: string;
        /**
         * Password for the selected key.
         *
         * @required when `signing` is provided.
         */
        keyPassword: string;
        /**
         * Enables APK Signature Scheme v1.
         *
         * @default implementation-defined by the Android build if omitted.
         */
        v1SigningEnabled?: boolean;
        /**
         * Enables APK Signature Scheme v2.
         *
         * @default implementation-defined by the Android build if omitted.
         */
        v2SigningEnabled?: boolean;
        /**
         * Enables APK Signature Scheme v3.
         *
         * @default implementation-defined by the Android build if omitted.
         */
        v3SigningEnabled?: boolean;
        /**
         * Enables APK Signature Scheme v4.
         *
         * @default implementation-defined by the Android build if omitted.
         */
        v4SigningEnabled?: boolean;
    };
    /**
     * Native build configuration.
     *
     * These values control Gradle / Android build behavior.
     */
    build?: {
        /**
         * Enables code minification/obfuscation for release builds.
         *
         * @default false
         */
        minifyEnabled?: boolean;
        /**
         * Enables unused resource shrinking.
         *
         * Usually meaningful only together with minification/release optimization.
         *
         * @default false
         */
        shrinkResources?: boolean;
        /**
         * JVM target used for Kotlin/Java compilation.
         *
         * @default '21'
         */
        jvmTarget?: string;
        /**
         * Kotlin version used by the native Android build.
         *
         * @default '2.0.21'
         */
        kotlinVersion?: string;
        /**
         * Android Gradle Plugin version used by the native build.
         *
         * @default '8.7.3'
         */
        agpVersion?: string;
        /**
         * Extra Gradle properties to inject as key/value pairs.
         *
         * @default {}
         * @example { MY_API_KEY: 'abc123' }
         */
        extraProperties?: Record<string, string>;
    };
}
